&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;6550p-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;8c2fp&quot; data-offset-key=&quot;6550p-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6550p-0-0&quot;&gt;&lt;span data-offset-key=&quot;6550p-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;You’ll implement features that power Elastic Defend user interface capabilities.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;8c2fp&quot; data-offset-key=&quot;emrl5-0-0&quot;&gt;
