&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Financial coaching + 5% pension match.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;40 hours of paid learning and development.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
